<script>
import flatPickr from 'vue-flatpickr-component';
import { Mandarin } from 'flatpickr/dist/l10n/zh';

import { countryOptions, tagOptions } from '@/enums/common';
import { addCollection, collectionIds } from '@/utils/setCollectIds';
import { ruleValidate } from '@/utils/ruleValidate';

import '@/assets/css/customFlatpickr.scss';

import pageCode from '@/enums/pageCodes';
import cardData from '@/enums/cardData';
import regionData from '@/enums/regionData';
import organizationData from '@/enums/organizationData';

export default {
  name: 'SubscribePage',
  components: {
    flatPickr,
  },
  layout: 'GatherLayout',
  async asyncData({ $axios }) {
    // 1.
    // return Promise.all([
    //   $axios.get('/getCardData'),
    //   $axios.get('/getCollectIds')
    // ]).then(([cardDataRes, collectIdsRes]) => {
    //   const abc = cardDataRes.data;
    //   const collects111 = collectIdsRes.data;
    //   return { abc, collects111 };
    // });
    try {
      const requests = [
        $axios.get('/goods', { params: { pagenum: 1, pagesize: 1 } }),
        $axios.get('/orders', { params: { pagenum: 1, pagesize: 1 } }),
        // $axios.post('https://123.com/goods', {
        //   params: { pagenum: 1, pagesize: 1 },
        // }),
      ];
      const responses = await Promise.allSettled(requests);
      const successfulResponses = responses
        .filter((response) => response.status === 'fulfilled')
        .map((response) => response.value.data);
      return {
        successfulResponses,
      };
    } catch (error) {
      console.error('Error:', error);
      return {
        successfulResponses: [],
      };
    }
  },
  data() {
    return {
      successfulResponses1: '',
      open: false,
      selectDateValue: '',
      selectDateValue2: '',
      pageContent: 0,
      monthsRange: [],
      rightCardOpen: true,
      datePickerConfig: {
        inline: true,
        mode: 'range',
        dateFormat: 'Y-m-d',
        monthSelectorType: 'static',
        locale: Mandarin,
      },
      searchForm: {
        type: '',
        region: [],
        country: [],
        organization: '',
        lowestPrice: null,
        highestPrice: null,
        buy: '',
      },

      collectionIds,
      tagOptions,
      cardData,
      ruleValidate,
      regionData,
      organizationData,
      countryOptions,
      pageCode,
    };
  },
  // async fetch() {
  //   this.successfulResponses1 = await this.$axios.get('/goodsqq', {params: {pagenum: 1, pagesize: 1}}).then(res => {
  //       return res.data;
  //     })
  // },
  // activated() {
  //   // Call fetch again if last fetch more than 30 sec ago
  //   if (this.$fetchState.timestamp <= Date.now() - 30000) {
  //     this.$fetch()
  //   }
  // },
  methods: {
    addCollection,
    doSomethingOnChange() {
      console.log('date1', this.selectDateValue);
      console.log('date2', this.selectDateValue2);
    },
    refresh() {
      this.selectDateValue = '';
      this.selectDateValue2 = '';
      this.monthsRange = [];
      this.$refs.searchForm.resetFields();
    },
  },
};
</script>

